local b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function b64dec(s)
    local result = {}
    local i = 1
    while i <= #s do
        local c1 = b64chars:find(s:sub(i,i),1)
        local c2 = b64chars:find(s:sub(i+1,i+2),1)
        local c3 = b64chars:find(s:sub(i+2,i+2),1)
        local c4 = b64chars:find(s:sub(i+3,i+3),1)
        if not c1 or not c2 then break end
        local bits = (c1-1)*262144 + (c2-1)*4096
        table.insert(result, string.char(math.floor(bits/65536)))
        if c3 then
            bits = bits + (c3-1)*64
            table.insert(result, string.char(math.floor(bits%65536/256)))
            if c4 then
                bits = bits + (c4-1)
                table.insert(result, string.char(bits%256))
            end
        end
        i = i + 4
    end
    return table.concat(result)
end

local function load_module(name)
    local src = module_sources[name]
    if not src then error(Tetra: module not found:  .. name) end
    local decoded = b64dec(src)
    local chunk, err = loadstring(decoded, "@" .. name)
    if not chunk then error(Tetra: failed to parse  .. name .. :  .. tostring(err)) end
    local ok, result = pcall(chunk)
    if not ok then error(Tetra: module  .. name ..  failed:  .. tostring(result)) end
    module_cache[name] = result
    return result
end

-- Run Tetra
local initFn = load_module(init)
if type(initFn) ~= function then
    error(Tetra: init.luau did not return a function (got  .. type(initFn) .. ), 0)
end

local env = { WindUI = load_module(WindUI) }
local ok, Tetra = pcall(initFn, env)
if not ok then
    error(Tetra: init failed:  .. tostring(Tetra), 0)
end

return Tetra
